"""
Measurements for the stance selection module (navigation design proposal, S6): the quick search scores of the candidates for the current scene, and the time of full check on one candidate.

    source .venv/bin/activate
    MUJOCO_GL=egl python experiments/stance_selection_timing.py [--maps data/reach_map] [--out data/logs]

Nothing in the scene, the staging or the settings is changed; one sim and render job (run it alone).

Quick search (the map query, src/stance_finder.find_stances): the scene of experiments/stance_from_map.py case "open_b45" (open bench, objects where they are now, grasp band 45 to 60 %), the 24 task
points labeled "either" (the VLA picks the hand; both arms preferred), headings -150 to -30 in 5 degree steps (the same headings as the finder runs), every pedestal height. Prints the time per
heading and the ranked candidates over all headings (score = distance to the edge of the valid region, cm; arm; the valid pedestal range), and how many are above a floor of 0, 0.5, 1, 2 and 3 cm.
full check on one candidate (the first of the ranking, heading restricted to -90 degrees as the staging does; and the stance now in TASK_CFG): the checks of src/stance_checks.StanceChecks at each
pedestal height of the candidate's valid range on a 1 cm grid (home clearance, placed-beaker clearance, then, where those pass, the neck solves, the pixel occlusion renders and the framing
slack), then the IK verification of experiments/stance_sensitivity.Runner.evaluate at the chosen height. Times each component and prints cold (the first stance: includes building the renderer) and
warm numbers. The IK verification is the left arm's (as in the current selection).
"""

import argparse
import json
import math
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

import stance_from_map as SFM  # noqa: E402
import stance_sensitivity as SS  # noqa: E402
from src.furniture_map import FurnitureMap  # noqa: E402
from src.stance_checks import StanceChecks  # noqa: E402
from src.stance_finder import find_stances, region_scores  # noqa: E402
from src.task_beaker_hotplate import apply_task_poses  # noqa: E402
from src.task_config import STANCE_CFG, TASK_CFG  # noqa: E402

FLOORS_CM = (0.0, 0.5, 1.0, 2.0, 3.0)


class Timer:
    """Wraps methods of an object so that every call's time is added to a named total."""

    def __init__(self):
        self.t, self.n = {}, {}

    def wrap(self, obj, name, label=None):
        label = label or name
        fn = getattr(obj, name)

        def timed(*a, **k):
            t0 = time.perf_counter()
            r = fn(*a, **k)
            self.t[label] = self.t.get(label, 0.0) + time.perf_counter() - t0
            self.n[label] = self.n.get(label, 0) + 1
            return r
        setattr(obj, name, timed)

    def take(self):
        out = {k: {"seconds": round(v, 3), "calls": self.n[k]} for k, v in self.t.items()}
        self.t, self.n = {}, {}
        return out


def main(args):
    maps = SFM.load_maps(args.maps)
    R = SS.Runner("open_b45", {**SFM.CASES["open_b45"], "cameras": True})
    ctx = R.ctx
    m = ctx.m
    m.body_pos[m.body("task_hotplate").id] = [ctx.hotplate_xy[0], ctx.hotplate_xy[1], ctx.top]
    data = ctx.data
    apply_task_poses(m, data, {**TASK_CFG, "beaker_xy": tuple(ctx.beaker_xy), "hotplate_xy": tuple(ctx.hotplate_xy)})
    mujoco.mj_forward(m, data)
    furniture = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    rg = ctx.rg
    qs = np.round(np.arange(0.0, 0.3001, 0.01), 4)
    pts = [{"p": p.tolist(), "arm": "either", "bin": None} for p in ctx.P]
    cfg = {**STANCE_CFG, "max_stances": 3}
    out = {"points": len(pts), "headings_deg": SFM.HEADINGS}

    print(f"quick search: {len(pts)} task points labeled either, {len(SFM.HEADINGS)} headings, {len(qs)} pedestal heights")
    per, cands, t_rs, raw_any, raw_both, cell = {}, [], [], {}, {}, None
    t_all = time.perf_counter()
    for h in SFM.HEADINGS:
        t0 = time.perf_counter()
        res = find_stances(pts, maps, furniture, rg, cfg=cfg, headings=[math.radians(h)], pedestal_qs=qs)
        per[h] = round(time.perf_counter() - t0, 2)
        cands += [{**c, "heading_deg": float(h)} for c in res]
        t1 = time.perf_counter()                                                 # the unthinned candidates: every floor cell of this heading, by the best score over the pedestal heights
        X, Y, Sc = region_scores(pts, maps, furniture, rg, math.radians(h), qs)
        t_rs.append(time.perf_counter() - t1)
        cell = float(X[0, 1] - X[0, 0])
        any_arm = np.maximum(Sc["left"].max(axis=0), Sc["right"].max(axis=0))
        both_arms = np.minimum(Sc["left"], Sc["right"]).max(axis=0)
        for f in FLOORS_CM:
            raw_any[f] = raw_any.get(f, 0) + int((any_arm * 100 > f).sum())
            raw_both[f] = raw_both.get(f, 0) + int((both_arms * 100 > f).sum())
    out["layer2_seconds_total"] = round(time.perf_counter() - t_all, 1)
    out["layer2_seconds_per_heading"] = per
    cands.sort(key=lambda c: (-c["tier"], -c["score"]))
    out["layer2_candidates"] = [{k: (round(v, 4) if isinstance(v, float) else v) for k, v in c.items() if k in ("x", "y", "heading_deg", "q", "q_lo", "q_hi", "arm", "score", "score_left", "score_right", "tier")} for c in cands]
    print(f"  quick search total {out['layer2_seconds_total']} s ({np.mean(list(per.values())):.1f} s per heading); {len(cands)} candidates (3 per heading at most)")
    print("  ranked (both arms first, then score): x, y, heading, pedestal q (range), arm, score cm")
    for c in cands[:20]:
        print(f"   x {c['x']:.2f} y {c['y']:.2f} h {c['heading_deg']:6.1f}  q {c['q']:.3f} ({c['q_lo']:.2f}..{c['q_hi']:.2f})  {c['arm']:5s}  score {100 * c['score']:.1f} cm")
    out["region_scores_seconds_per_heading"] = round(float(np.mean(t_rs)), 2)
    out["cell_m"], out["heading_step_deg"] = cell, STANCE_CFG["heading_step_deg"]
    out["unthinned_cells_above_floor_any_arm"] = {str(f): n for f, n in raw_any.items()}
    out["unthinned_cells_above_floor_both_arms"] = {str(f): n for f, n in raw_both.items()}
    print(f"  the unthinned candidates (floor cells x headings; cell {1000 * cell:.0f} mm, heading step {STANCE_CFG['heading_step_deg']} deg), above a floor (cm): any arm " + ", ".join(f"{f}: {raw_any[f]}" for f in FLOORS_CM)
          + "; both arms " + ", ".join(f"{f}: {raw_both[f]}" for f in FLOORS_CM) + f"   (region_scores {np.mean(t_rs):.1f} s per heading)")
    out["above_floor"] = {f"{f}": sum(c["score"] * 100 > f for c in cands) for f in FLOORS_CM}
    print("  candidates above a floor (cm): " + ", ".join(f"{f}: {n}" for f, n in out["above_floor"].items()))
    both = [c for c in cands if c["tier"] == 1]
    out["both_arms"] = len(both)
    print(f"  both arms reach every point: {len(both)} of {len(cands)}")

    print("\nfull check on one candidate")
    chk = StanceChecks(m, data, rg["base_z"])
    T = Timer()
    for name in ("home_clearance", "beaker_on_hotplate_clearance", "neck_spread", "occlusion", "framing_slack"):
        T.wrap(chk, name)
    T.wrap(R, "evaluate", "ik_verification")
    heading = math.radians(-90.0)
    at90 = [c for c in cands if abs(c["heading_deg"] + 90.0) < 1e-6]
    first = at90[0]
    targets = {"first candidate at -90 deg (quick search rank %d of %d at that heading)" % (1, len(at90)): (first["x"], first["y"], first["q_lo"], first["q_hi"]),
               "the stance in TASK_CFG (staging_xy, pedestal_q)": (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1], TASK_CFG["pedestal_q"] - 0.05, TASK_CFG["pedestal_q"] + 0.05)}
    out["layer3"] = {}
    for label, (x, y, q_lo, q_hi) in targets.items():
        for rep in ("cold" if not out["layer3"] else "warm", "warm"):
            T.take()
            t0 = time.perf_counter()
            rows = []
            for q in [float(q) for q in qs if q_lo - 1e-9 <= q <= q_hi + 1e-9]:
                rows.append(SFM.req_row(chk, (x, y, heading, q)))
            t_req = time.perf_counter() - t0
            passing = [i for i, r in enumerate(rows) if r["ok"]]
            q_ok = [float(q) for q in qs if q_lo - 1e-9 <= q <= q_hi + 1e-9]
            t1 = time.perf_counter()
            ev = None
            if passing:
                q_mid = q_ok[passing[len(passing) // 2]]
                ev = R.evaluate(np.array([x, y, heading, q_mid]))
            t_ik = time.perf_counter() - t1
            parts = T.take()
            out["layer3"].setdefault(label, []).append({"run": rep, "heights_checked": len(rows), "heights_passing": len(passing), "requirements_seconds": round(t_req, 2), "ik_seconds": round(t_ik, 2),
                                                        "total_seconds": round(t_req + t_ik, 2), "components": parts, "ik_ok": None if ev is None else bool(ev["points_ok_self"] == ev["points"])})
            r = out["layer3"][label][-1]
            print(f"  {label}: {rep}: {r['heights_checked']} pedestal heights, {r['heights_passing']} pass; requirements {r['requirements_seconds']} s, IK verification {r['ik_seconds']} s, total {r['total_seconds']} s")
            for k, v in parts.items():
                print(f"      {k:30s} {v['seconds']:7.2f} s in {v['calls']} calls")
            if rep == "warm":
                break
    p = Path(args.out) / f"stance_selection_timing_{time.strftime('%Y%m%d_%H%M%S')}.json"
    p.write_text(json.dumps(out, indent=1))
    print(f"\nwritten {p}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--maps", default=str(PROJECT_ROOT / "data" / "reach_map"))
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "logs"))
    main(ap.parse_args())
